// All use `.svg-base { fill: currentColor }` semantics via fill="currentColor".

type P = { className?: string; title?: string };
const S = ({ d, className, title, box = "0 0 32 32" }: P & { d: string; box?: string }) => (
  <svg
    viewBox={box}
    className={className}
    role="img"
    aria-label={title}
    aria-hidden={!title}
    focusable="false"
  >
    <path fill="currentColor" d={d} />
  </svg>
);

